        A[i], A[max_row] = A[max_row], A[i]

        # Eliminate below pivot
        for j in range(i + 1, n):
            factor = A[j][i] / A[i][i]
            for k in range(n + 1):
                A[j][k] -= factor * A[i][k]

    # Back-substitute to get solution
    x = [0] * n
    for i in range(n - 1, -1, -1):
        x[i] = A[i][n] / A[i][i]
        for j in range(i + 1, n):
            x[i] -= A[i][j] * x[j]

    return x

def solve_linear_system(A, b):
    A_aug = [row + [b[i]] for i, row in enumerate(A)]
